const typeIds = archetypes.map(a=>a.id);
export const childAgeStages = [
  {id:'baby', label:'0–2 года', name:'младенец и малыш'},
  {id:'preschool', label:'3–6 лет', name:'дошкольник'},
  {id:'school', label:'7–12 лет', name:'младший школьник'},
  {id:'teen', label:'13–17 лет', name:'подросток'},
  {id:'adult', label:'18+ лет', name:'взрослый ребёнок'},
];
export function childStageForMonths(months){
  if(!Number.isFinite(months)||months<0)return null;
  if(months<36)return'baby';if(months<84)return'preschool';if(months<156)return'school';if(months<216)return'teen';return'adult';
}
export function getFamilyDynamicsReading(childAgesMonths=[],typeId='staff'){
  const ages=childAgesMonths.filter(age=>Number.isInteger(age)&&age>=0).sort((a,b)=>a-b);
  if(!ages.length)return'';
  const plural=(n,one,few,many)=>{const mod100=n%100,mod10=n%10;return mod100>=11&&mod100<=14?many:mod10===1?one:mod10>=2&&mod10<=4?few:many;};
  const formatAge=months=>months<12?`${months} ${plural(months,'месяц','месяца','месяцев')}`:`${Math.floor(months/12)} ${plural(Math.floor(months/12),'год','года','лет')}${months%12?` ${months%12} мес.`:''}`;
  const typeJabs={
    staff:'А штаб всё ещё хочет собрать расписания в одну голову. Угадаешь чью.',
    queen:'Количество детей не отменяет право закрыть приёмную. Дверь, кстати, не требует семейного голосования.',
    detective:'Возраст меняет улики: сон, варежка или сообщение без ответа. Холодильник пока вне подозрения.',
    relaxed:'Количество детей не измеряет нагрузку. Идеальную картинку можно отпустить без пресс-релиза.',
    rescue:'Не каждый семейный сигнал требует выезда спасательной бригады из одного человека.',
    chat:'Чат мог бы быть короче на 86 сообщений, если бы все читали закреп. Мечты тоже учитываем.',
    enlightened:'Возраст у детей разный, нервная система у тебя одна. Курсы повышения квалификации не входят в комплект.',
    circus:'Разный возраст — разный реквизит. Уборщица в финале пока одна и, сюрприз, это не план.'
  };
  if(ages.length===1)return `В семье один ребёнок: ${formatAge(ages[0])}. Возраст подстроил вопросы; вывод «один — значит легко» тест не делает. ${typeJabs[typeId]||typeJabs.staff}`;
  const gaps=ages.slice(1).map((age,index)=>age-ages[index]);
  const youngest=ages.filter(age=>age<36).length;
  const stageLabels=[...new Set(ages.map(childStageForMonths).filter(Boolean))].map(id=>childAgeStages.find(stage=>stage.id===id)?.label).filter(Boolean);
  const ageText=ages.map(formatAge).join(', ');
  const gapText=gaps.map(gap=>`${formatAge(gap)}${gap===0?' (ровесники)':gap<24?' (почти погодки)':gap<60?' (разница 2–4 года)':' (большая разница)'}`).join(', ');
  const overlap=youngest>=2?` У ${youngest} детей до трёх лет потребности могут совпасть по расписанию — семейный диспетчер это заметил.`:'';
  const stages=stageLabels.length>1?` Возрастные маршруты смешаны: ${stageLabels.join(' + ')}.`:'';
  return `В семье ${ages.length} ${plural(ages.length,'ребёнок','ребёнка','детей')}: ${ageText}. Между детьми: ${gapText}.${overlap}${stages} Состав семьи добавляет контекст, а не баллы за сложность. ${typeJabs[typeId]||typeJabs.staff}`;
}

